    __stickytape_write_module('action.py', b'"""Building blocks for converting the bash setup scripts into readable, re-runnable steps.\n\nAn Action is one unit of change with three phases:\n\n    precheck()   True if the desired state already holds (run is skipped)\n    run()        make the change\n    postcheck()  True if the desired state now holds (False aborts)\n\nLike `set -e`, a failure stops the runner unless the action opts in via continue_on_error\n(the equivalent of a bash `|| true`).\n"""\n\nfrom __future__ import annotations\n\nimport enum\nimport logging\nfrom abc import ABC, abstractmethod\nfrom dataclasses import dataclass\nfrom typing import Iterable\n\nlog = logging.getLogger(__name__)\n\n\nclass Status(enum.Enum):\n    SKIPPED = "skipped"  # precheck passed, nothing to do\n    CHANGED = "changed"  # run executed and postcheck passed\n    UNVERIFIED = "unverified"  # run executed, but the action defines no postcheck\n    FAILED = "failed"    # only seen for continue_on_error actions\n\n\nclass ActionError(RuntimeError):\n    """An action failed in run() or its postcheck()."""\n\n    def __init__(self, action: "Action", message: str):\n        super().__init__(f"{action.name}: {message}")\n        self.action = action\n\n\n@dataclass(frozen=True)\nclass Result:\n    action: "Action"\n    status: Status\n    error: BaseException | None = None\n\n\nclass Action(ABC):\n    #: Set True for steps that mirror a bash `|| true`: a failure is logged, not raised.\n    continue_on_error: bool = False\n    #: Label shown in log lines; set by whoever assembles the action list.\n    section: str = ""\n    #: A precheck() that returns False may set this to say what is off; it is logged and shown by the check run.\n    precheck_detail: str = ""\n    #: A postcheck() that returns False may set this to say why; it is appended to the failure message.\n    postcheck_detail: str = ""\n\n    def __init__(self, name: str):\n        self.name = name\n\n    @abstractmethod\n    def precheck(self) -> bool:\n        """Return True when the desired state already holds, so run() is skipped."""\n\n    @abstractmethod\n    def run(self) -> None:\n        """Apply the change. Raise on failure."""\n\n    @abstractmethod\n    def postcheck(self) -> bool:\n        """Return True when the desired state holds after run()."""\n\n    def verifiable(self) -> bool:\n        """False when this action has nothing to check after run(); it then ends UNVERIFIED, not CHANGED."""\n        return True\n\n    def _log(self, phase: str, message: str = "", level: int = logging.INFO) -> None:\n        tag = f"[{self.section or \'-\'}][{phase}]"\n        log.log(level, "%-22s %s%s", tag, self.name, f" -> {message}" if message else "")\n\n    def execute(self) -> Result:\n        """Run the precheck -> run -> postcheck sequence for this action."""\n        phase = "Precheck"\n        try:\n            satisfied = self.precheck()\n            if satisfied:\n                self._log("Precheck", "satisfied, skipping")\n                return Result(\n                    action=self,\n                    status=Status.SKIPPED,\n                )\n            self._log("Precheck", f"not satisfied: {self.precheck_detail}" if self.precheck_detail else "not satisfied")\n            phase = "Run"\n            self._log("Run")\n            self.run()\n            if not self.verifiable():\n                self._log("Postcheck", "skipped (no check defined)")\n                return Result(\n                    action=self,\n                    status=Status.UNVERIFIED,\n                )\n            phase = "Postcheck"\n            if not self.postcheck():\n                raise ActionError(\n                    action=self,\n                    message="postcheck failed after run"\n                    + (f": {self.postcheck_detail}" if self.postcheck_detail else ""),\n                )\n            self._log("Postcheck", "ok")\n        except Exception as exc:\n            if self.continue_on_error:\n                self._log(phase, f"FAILED (ignored): {exc}", logging.WARNING)\n                return Result(\n                    action=self,\n                    status=Status.FAILED,\n                    error=exc,\n                )\n            self._log(phase, f"FAILED: {exc}", logging.ERROR)\n            if isinstance(exc, ActionError):\n                raise\n            raise ActionError(\n                action=self,\n                message=str(exc),\n            ) from exc\n        return Result(\n            action=self,\n            status=Status.CHANGED,\n        )\n\n    def __repr__(self) -> str:\n        return f"{type(self).__name__}({self.name!r})"\n\n\ndef run_actions(actions: Iterable[Action]) -> list[Result]:\n    """Execute actions in order, stopping at the first non-ignorable failure. Logs a summary at the end."""\n    results: list[Result] = []\n    try:\n        for action in actions:\n            results.append(action.execute())\n    finally:\n        counts = {s: sum(r.status is s for r in results) for s in Status}\n        log.info("Summary: %d changed, %d unverified, %d skipped, %d failed (ignored)",\n                 counts[Status.CHANGED], counts[Status.UNVERIFIED], counts[Status.SKIPPED], counts[Status.FAILED])\n    return results\n')
    __stickytape_write_module('config.py', b'"""Settings of alma-setup: the shared ones (shared/base_config.py) plus the AlmaLinux specifics.\n\nRun-time overrides come from the environment (put them AFTER sudo, which resets it):\n    sudo SYSTEM_HOSTNAME=foo STATIC_IP=192.168.1.50/24 STATIC_GATEWAY=192.168.1.1 python3 alma-setup/main.py\nEverything else is plain configuration: edit it in place.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\n\nfrom base_config import MIDFIX, Config as BaseConfig, env_help  # noqa: F401  (MIDFIX is re-exported for the sections)\n\n# Shown by `main.py --help`. Keep in step with the config fields and from_env in base_config.py.\nENV_HELP = env_help("console keymap (default: jp106); empty keeps the current one")\n\n\n@dataclass(frozen=True)\nclass Config(BaseConfig):\n    keymap: str = "jp106"     # console keymap (Japanese JIS); empty keeps the current one\n    admin_group: str = "wheel"\n\n    # --- network ---\n    net_connection: str = ""  # NetworkManager connection on static_iface, for a DNS-only change\n    nm_priority: int = 100  # above the stock profile (0) so this one wins\n\n    # --- authselect ---\n    authselect_profile: str = "local"\n    authselect_features: tuple[str, ...] = ("without-nullok", "with-faillock")\n\n    packages: tuple[str, ...] = (\n        "curl", "wget", "git", "vim-enhanced", "htop", "tmux", "gcc", "make", "python3", "python3-pip",\n        "qemu-guest-agent", "nftables", "dnf-automatic", "dnf-plugins-core", "audit", "audit-rules",\n        "chrony", "cronie", "at", "rsyslog", "logrotate",\n    )\n\n    dnf_dropin_dir: str = "/etc/systemd/system/dnf-automatic.service.d"\n\n    # --- derived: hostname ---\n    @property\n    def static_hostname(self) -> str:\n        """The FQDN if there is one (RHEL convention), else the short name."""\n        return self.fqdn or self.hostname\n\n    @property\n    def hosts_line(self) -> str:\n        return f"127.0.1.1 {\' \'.join(f\'{self.fqdn} {self.hostname}\'.split())} {self.hosts_marker}"\n\n    # --- derived: paths ---\n    @property\n    def nm_conf(self) -> str:\n        return f"/etc/NetworkManager/system-connections/{MIDFIX}-static.nmconnection"\n\n    @property\n    def nm_connection(self) -> str:\n        return f"{MIDFIX}-static"\n')
    __stickytape_write_module('base_config.py', b'"""Settings common to all distro setup scripts; each distro\'s config.py subclasses Config and adds its own.\n\nRun-time overrides come from the environment (put them AFTER sudo, which resets it):\n    sudo SYSTEM_HOSTNAME=foo STATIC_IP=192.168.1.50/24 STATIC_GATEWAY=192.168.1.1 python3 <distro>/main.py\nEverything else is plain configuration: edit it in place.\n"""\n\nfrom __future__ import annotations\n\nimport os\nfrom dataclasses import dataclass\n\nMIDFIX = "from-setup"\n\n\ndef env_help(keymap_line: str) -> str:\n    """The environment variables both distros read. Shown by `main.py --help`; keep in step with from_env."""\n    return f"""\\\nenvironment (put them AFTER sudo, which resets the environment). Any value left unset keeps its current setting:\n  SYSTEM_HOSTNAME  short hostname; used for the /etc/hosts alias and to derive the FQDN\n  SYSTEM_DOMAIN    domain; with SYSTEM_HOSTNAME, derives the FQDN as <hostname>.<domain>\n  SYSTEM_FQDN      FQDN override (default: derived as above)\n  STATIC_IP        IPv4 CIDR, e.g. 192.168.1.50/24; makes the address static (default: current address)\n  STATIC_GATEWAY   IPv4 gateway; makes the address static (default: current default-route gateway)\n  STATIC_DNS       space-separated DNS servers (default: current). Alone, changes only DNS, address untouched\n  STATIC_IFACE     interface (default: interface of the current default route)\n  KEYMAP           {keymap_line}\n  ADMIN_PUBKEY_FILE  local file with the admin public key (ed25519); default: download it from GitHub\n  SUDO_USER        set by sudo, not by you: this account is removed too, once admin and service accounts are ready\n"""\n\n\n@dataclass(frozen=True)\nclass Config:\n    # --- run-time overrides (see from_env) ---\n    hostname: str = ""        # short name; used for the /etc/hosts alias and to derive fqdn\n    domain: str = ""\n    fqdn: str = ""            # derived as <lowercased hostname>.<domain> when both are set\n    static_ip: str = ""       # IPv4 CIDR; empty keeps the current network config\n    static_gateway: str = ""  # empty = gateway of the current default route\n    static_dns: str = ""      # space-separated\n    static_iface: str = ""    # empty = interface of the current default route\n    admin_pubkey: str = ""    # filled in by preflight\n    admin_pubkey_file: str = ""  # local key file; when set, nothing is downloaded (works offline)\n    keymap: str = ""          # console keymap; empty keeps the current one (distro config sets the default)\n    sudo_user: str = ""       # account that ran sudo; pruned only once admin and service accounts are ready\n    # --- network change, decided by preflight.resolve_network; leave at the defaults ---\n    net_action: str = ""      # "" = no change, "dns" = DNS only (address untouched), "static" = write a static address\n    net_dhcp: bool = False    # the address on static_iface is DHCP-supplied, so DHCP DNS must be ignored\n\n    # --- accounts ---\n    admin_user: str = "devola"\n    service_user: str = "popola"\n    admin_group: str = ""     # set by the distro (wheel / sudo)\n    admin_shell: str = "/bin/bash"\n    service_shell: str = "/usr/sbin/nologin"\n    service_comment: str = "Service Account"\n    # Pre-hashed passwords. Generate with: openssl passwd -6 \'your_password_here\'\n    root_password_hash: str = "$6$N2iKTCTMzAmc51w4$Ohp2YKKOQbHmGezRtJSJYg1BdsirMy70L4mUjRg/o5M9xSj45UHf.2w.CHTcSmCh4c2KsrDxnEhoYj3RsQCb71" # intentional, password is high entropy.\n    admin_password_hash: str = "$6$TsJ5LrQMrfwVrUJi$pdbXq3DnZZ1e6PJy8ex.xesPUHmWzmuth5RhWlSrKzYKe1jsrvaWrIidZLOD7AwJZuVMNKAIbTuNlf85H4.oU." # intentional, password is high entropy.\n    admin_pubkey_url: str = "https://raw.githubusercontent.com/reverseon/ishiori-ssot/refs/heads/main/portable/files/ishiori-master-key.pub"\n\n    # --- sudo / su ---\n    sudo_log: str = "/var/log/sudo.log"\n    su_bin: str = "/usr/bin/su"\n    su_mode: int = 0o4750  # group-owned, setuid kept, other users get no execute\n\n    # --- ssh ---\n    ssh_port: int = 22\n\n    # --- network ---\n    static_apply_delay: str = "5s"\n\n    @classmethod\n    def from_env(cls, env: dict[str, str] | None = None) -> "Config":\n        env = os.environ if env is None else env\n        hostname, domain, fqdn = env.get("SYSTEM_HOSTNAME", ""), env.get("SYSTEM_DOMAIN", ""), env.get("SYSTEM_FQDN", "")\n        if not fqdn and hostname and domain:\n            fqdn = f"{hostname.lower()}.{domain}"\n        return cls(\n            hostname=hostname, domain=domain, fqdn=fqdn, keymap=env.get("KEYMAP", cls.keymap),\n            sudo_user=env.get("SUDO_USER", ""), admin_pubkey_file=env.get("ADMIN_PUBKEY_FILE", ""),\n            static_ip=env.get("STATIC_IP", ""), static_gateway=env.get("STATIC_GATEWAY", ""),\n            static_dns=env.get("STATIC_DNS", ""), static_iface=env.get("STATIC_IFACE", ""),\n        )\n\n    # --- derived: hostname ---\n    @property\n    def hosts_file(self) -> str:\n        return "/etc/hosts"\n\n    @property\n    def hosts_marker(self) -> str:\n        return f"# {MIDFIX}-hostname"\n\n    # --- derived: paths (all named after MIDFIX so they are recognisably ours) ---\n    @property\n    def ssh_conf(self) -> str:\n        # 00- prefix: sshd keeps the first value per option, so this must sort before the other drop-ins\n        return f"/etc/ssh/sshd_config.d/00-{MIDFIX}-ssh.conf"\n\n    @property\n    def ssh_banner(self) -> str:\n        return f"/etc/ssh/banner-{MIDFIX}.net"\n\n    @property\n    def admin_ssh_dir(self) -> str:\n        return f"/home/{self.admin_user}/.ssh"\n\n    @property\n    def admin_authorized_keys(self) -> str:\n        return f"{self.admin_ssh_dir}/authorized_keys"\n\n    @property\n    def sudoers_dir(self) -> str:\n        return "/etc/sudoers.d"\n\n    @property\n    def sudo_conf(self) -> str:\n        return f"{self.sudoers_dir}/99-{MIDFIX}-sudo"\n\n    @property\n    def admin_sudoers_conf(self) -> str:\n        return f"{self.sudoers_dir}/99-{MIDFIX}-{self.admin_user}"\n\n    @property\n    def service_sudoers_conf(self) -> str:\n        return f"{self.sudoers_dir}/99-{MIDFIX}-{self.service_user}"\n\n    # su guard\n    @property\n    def su_guard_bin(self) -> str:\n        return f"/usr/local/sbin/{MIDFIX}-su-guard"\n\n    @property\n    def su_guard_service(self) -> str:\n        return f"{MIDFIX}-su-guard.service"\n\n    @property\n    def su_guard_path(self) -> str:\n        return f"{MIDFIX}-su-guard.path"\n\n    @property\n    def su_guard_timer(self) -> str:\n        return f"{MIDFIX}-su-guard.timer"\n\n    # reboot-check\n    @property\n    def reboot_notice_file(self) -> str:\n        return f"/run/motd.d/50-{MIDFIX}-reboot-required"\n\n    @property\n    def reboot_check_bin(self) -> str:\n        return f"/usr/local/sbin/{MIDFIX}-reboot-check"\n\n    @property\n    def nft_rules_conf(self) -> str:\n        return f"/etc/nftables/{MIDFIX}-inet-filter.nft"\n\n    @property\n    def nft_include(self) -> str:\n        return f\'include "{self.nft_rules_conf}"\'\n')
