    __stickytape_write_module('sections/firewall.py', b'"""nftables as the only firewall manager."""\n\nimport texts\nfrom actions import EnsureDir, EnsureLine, Systemctl, WriteFile\nfrom config import Config\n\n\ndef actions(c: Config):\n    return [\n        EnsureDir(\n            path="/etc/nftables",\n        ),\n        WriteFile(\n            path=c.nft_rules_conf,\n            text=texts.nft_rules(c),\n        ),\n        # Include the ruleset in the main nftables config so it persists across reboots\n        EnsureLine(\n            path="/etc/sysconfig/nftables.conf",\n            line=c.nft_include,\n        ),\n        # Mask firewalld so it cannot load a second ruleset\n        Systemctl(\n            verb="disable_now",\n            units=["firewalld"],\n            continue_on_error=True,\n        ),\n        Systemctl(\n            verb="mask",\n            units=["firewalld"],\n            continue_on_error=True,\n        ),\n        Systemctl(\n            verb="enable",\n            units=["nftables"],\n        ),\n        Systemctl(\n            verb="restart",\n            units=["nftables"],\n        ),\n    ]\n')
    __stickytape_write_module('sections/identity.py', b'"""Accounts and local access policy: MOTD, sudo, passwords, faillock, admin user, su restriction, admin SSH key."""\n\nimport os\n\nimport texts\nfrom actions import Cmd, EnsureDir, Func, Systemctl, WriteFile, ok, out, sh\nfrom config import MIDFIX, Config\n\nUNITS = "/etc/systemd/system"\n\n\ndef password(user: str, hash_: str) -> Cmd:\n    def current() -> bool:\n        fields = out("getent", "shadow", user).split(":")\n        return len(fields) > 1 and fields[1] == hash_\n    return Cmd(\n        name=f"password for {user}",\n        argv=["chpasswd", "-e"],\n        input=f"{user}:{hash_}\\n",\n        done=current,\n    )\n\n\ndef _su_ok(c: Config) -> bool:\n    import grp\n    st = os.stat(c.su_bin)\n    return (st.st_mode & 0o7777) == c.su_mode and grp.getgrgid(st.st_gid).gr_name == c.admin_group\n\n\ndef _su_restrict(c: Config) -> None:\n    sh("chgrp", c.admin_group, c.su_bin)\n    os.chmod(c.su_bin, c.su_mode)\n\n\ndef _authselect_ok(c: Config) -> bool:\n    current = out("authselect", "current", "-r").split()\n    return bool(current) and current[0] == c.authselect_profile and set(c.authselect_features) <= set(current[1:])\n\n\ndef actions(c: Config):\n    result = [\n        WriteFile(\n            path="/etc/motd",\n            text=texts.motd(c),\n        ),\n        EnsureDir(\n            path=c.sudoers_dir,\n        ),\n        WriteFile(\n            path=c.sudo_conf,\n            text=texts.sudo_conf(c),\n            mode=0o440,\n            validator=["visudo", "-c", "-f"],\n        ),\n        password("root", c.root_password_hash),\n        # Disallow empty passwords via authselect\n        Cmd(\n            name="authselect profile",\n            argv=["authselect", "select", c.authselect_profile, *c.authselect_features, "--force"],\n            done=lambda: _authselect_ok(c),\n        ),\n        # Limit password guessing (stock file is comments only, so we own it whole)\n        WriteFile(\n            path="/etc/security/faillock.conf",\n            text=texts.FAILLOCK_CONF,\n        ),\n        # Session timeout (15 minutes idle); a default, not a hard control\n        WriteFile(\n            path=f"/etc/profile.d/{MIDFIX}-timeout.sh",\n            text=texts.TIMEOUT_CONF,\n        ),\n        # Admin user\n        Cmd(\n            name=f"create {c.admin_user}",\n            argv=["useradd", "-m", "-s", c.admin_shell, c.admin_user],\n            done=lambda: ok("id", "-u", c.admin_user),\n        ),\n        password(c.admin_user, c.admin_password_hash),\n        Cmd(\n            name=f"{c.admin_user} in {c.admin_group}",\n            argv=["usermod", "-aG", c.admin_group, c.admin_user],\n            done=lambda: c.admin_group in out("id", "-nG", c.admin_user).split(),\n        ),\n        # Restrict su to the admin group (re-applied by the su-guard units after package updates)\n        Func(\n            name=f"restrict {c.su_bin}",\n            run=lambda: _su_restrict(c),\n            pre=lambda: _su_ok(c),\n            post=lambda: _su_ok(c),\n        ),\n        WriteFile(\n            path=c.su_guard_bin,\n            text=texts.su_guard_bin(c),\n            mode=0o755,\n            relabel=True,\n        ),\n        WriteFile(\n            path=f"{UNITS}/{c.su_guard_service}",\n            text=texts.su_guard_service(c),\n        ),\n        WriteFile(\n            path=f"{UNITS}/{c.su_guard_path}",\n            text=texts.su_guard_path(c),\n        ),\n        WriteFile(\n            path=f"{UNITS}/{c.su_guard_timer}",\n            text=texts.su_guard_timer(c),\n        ),\n        Systemctl(\n            verb="daemon_reload",\n            units=[c.su_guard_service, c.su_guard_path, c.su_guard_timer],\n        ),\n        Systemctl(\n            verb="enable_now",\n            units=[c.su_guard_path, c.su_guard_timer],\n        ),\n        # Admin sudo access (password required)\n        WriteFile(\n            path=c.admin_sudoers_conf,\n            text=texts.admin_sudoers(c),\n            mode=0o440,\n            validator=["visudo", "-c", "-f"],\n        ),\n        # Authorize the master public key for the admin user\n        EnsureDir(\n            path=c.admin_ssh_dir,\n            mode=0o700,\n            owner=c.admin_user,\n            group=c.admin_user,\n            relabel=True,\n        ),\n        WriteFile(\n            path=c.admin_authorized_keys,\n            text=c.admin_pubkey,\n            mode=0o600,\n            owner=c.admin_user,\n            group=c.admin_user,\n            relabel=True,\n        ),\n    ]\n    return result\n')
    __stickytape_write_module('sections/keyboard.py', b'"""Console and X11 keyboard layout (Japanese JIS by default). Set KEYMAP to change; empty leaves it alone."""\n\nfrom actions import Cmd, out\nfrom config import Config\n\n\ndef _current() -> str:\n    for line in out("localectl", "status").splitlines():\n        key, _, value = line.partition(":")\n        if key.strip() == "VC Keymap":\n            return value.strip()\n    return ""\n\n\ndef actions(c: Config):\n    if not c.keymap:\n        return []\n    return [\n        # localectl writes /etc/vconsole.conf and derives the matching X11 layout from the console keymap\n        Cmd(\n            name=f"set keymap {c.keymap}",\n            argv=["localectl", "set-keymap", c.keymap],\n            done=lambda: _current() == c.keymap,\n        ),\n    ]\n')
    __stickytape_write_module('sections/network.py', b'"""The network change decided by preflight.resolve_network. A static address is written as a NetworkManager keyfile;\na DNS-only change is applied to the live connection and leaves the address alone. Both are written before AIDE (so\nthe baseline includes them). A static address is activated as the very last step of the whole script: the address\nchange drops an SSH session on the old address, so nothing may run after it."""\n\nimport texts\nfrom actions import Cmd, WriteFile, out\nfrom config import MIDFIX, Config\n\n\ndef _wanted_dns(c: Config) -> list[str]:\n    return sorted(c.static_dns.split())\n\n\ndef _configured_dns(c: Config) -> bool:\n    """The connection\'s ipv4.dns holds the wanted servers."""\n    return sorted(out("nmcli", "-g", "ipv4.dns", "connection", "show", c.net_connection).replace(",", " ").split()) \\\n        == _wanted_dns(c)\n\n\ndef _applied_dns(c: Config) -> bool:\n    """The device is using the wanted servers."""\n    return sorted(out("nmcli", "-g", "IP4.DNS", "device", "show", c.static_iface).replace(",", " ").split()) \\\n        == _wanted_dns(c)\n\n\ndef write(c: Config):\n    if c.net_action == "static":\n        return [\n            WriteFile(\n                path=c.nm_conf,\n                text=texts.nm_keyfile(c),\n                mode=0o600,\n                relabel=True,\n            ),\n            Cmd(\n                name="reload NetworkManager",\n                argv=["nmcli", "connection", "reload"],\n            ),\n        ]\n    if c.net_action == "dns":\n        return [\n            Cmd(\n                name=f"set DNS on {c.net_connection} to {c.static_dns}",\n                argv=["nmcli", "connection", "modify", c.net_connection,\n                      "ipv4.dns", ",".join(c.static_dns.split()),\n                      # DHCP-supplied DNS would be merged in otherwise\n                      "ipv4.ignore-auto-dns", "yes" if c.net_dhcp else "no"],\n                done=lambda: _configured_dns(c),\n            ),\n        ]\n    return []\n\n\ndef _active(c: Config) -> bool:\n    return c.nm_connection in out("nmcli", "-t", "-f", "NAME", "connection", "show", "--active").splitlines()\n\n\ndef activate(c: Config):\n    if c.net_action == "dns":\n        # No address change, so nothing to delay: re-apply the DNS to the device directly\n        return [\n            Cmd(\n                name=f"apply DNS on {c.static_iface} (address unchanged)",\n                argv=["nmcli", "device", "reapply", c.static_iface],\n                done=lambda: _applied_dns(c),\n            ),\n        ]\n    if c.net_action == "static":\n        # Delayed via a transient systemd unit so the script exits cleanly first\n        return [\n            Cmd(\n                name=f"activate {c.nm_connection} in {c.static_apply_delay} (an SSH session on the old address will drop)",\n                argv=[\n                    "systemd-run",\n                    f"--unit={MIDFIX}-static-ip-apply",\n                    f"--on-active={c.static_apply_delay}",\n                    "nmcli", "connection", "up", c.nm_connection,\n                ],\n                done=lambda: _active(c),\n                # The change lands after this script has exited, so there is nothing to verify here\n                verify_after_run=False,\n            ),\n        ]\n    return []\n')
    __stickytape_write_module('sections/packages.py', b'"""Security updates, repositories and base tooling, then time sync and job schedulers."""\n\nfrom actions import Cmd, DnfInstall, Systemctl, out, sh\nfrom config import Config\n\n\ndef _no_security_updates() -> bool:\n    """`dnf check-update` exits 0 when nothing is pending, 100 when updates exist, 1 on error."""\n    return sh("dnf", "check-update", "--security", "-q", check=False).returncode == 0\n\n\ndef _crb_enabled() -> bool:\n    return any(line.split()[:1] == ["crb"] for line in out("dnf", "repolist", "--enabled", "-q").splitlines())\n\n\ndef actions(c: Config):\n    return [\n        # Security updates only (same policy as dnf-automatic), then base tooling\n        Cmd(\n            name="dnf upgrade --security",\n            argv=["dnf", "upgrade", "--security", "-y"],\n            done=_no_security_updates,\n        ),\n        # Both come from the stock repos, so one transaction. Everything after needs EPEL\'s metadata,\n        # which only exists once epel-release is installed, so c.packages must be a separate transaction.\n        DnfInstall(\n            packages=["dnf-plugins-core", "epel-release"],\n        ),\n        # EPEL packages can depend on CodeReady Builder (crb); config-manager comes from dnf-plugins-core\n        Cmd(\n            name="enable crb repo",\n            argv=["dnf", "config-manager", "--set-enabled", "crb"],\n            done=_crb_enabled,\n        ),\n        DnfInstall(\n            packages=c.packages,\n        ),\n        Systemctl(\n            verb="enable_now",\n            units=["chronyd"],\n        ),\n        Systemctl(\n            verb="enable_now",\n            units=["crond"],\n        ),\n        Systemctl(\n            verb="enable_now",\n            units=["atd"],\n        ),\n    ]\n')
    __stickytape_write_module('sections/preflight.py', b'"""Every input check runs here, before the first change to the system, so a bad value aborts a clean run."""\n\nimport os\nimport subprocess\nimport tempfile\nfrom dataclasses import replace\n\nimport netcheck\nfrom actions import out\nfrom config import Config\nfrom pubkey import load_pubkey\n\n\nclass PreflightError(RuntimeError):\n    pass\n\n\ndef live_dns(iface: str) -> list[str]:\n    return out("nmcli", "-g", "IP4.DNS", "device", "show", iface).replace(",", " ").split()\n\n\ndef _live_connection(iface: str) -> str:\n    name = out("nmcli", "-g", "GENERAL.CONNECTION", "device", "show", iface)\n    return "" if name in ("", "--") else name\n\n\ndef resolve_network(c: Config) -> Config:\n    """The shared decision (netcheck), plus the NetworkManager connection that DNS-only changes apply to."""\n    c = netcheck.resolve_network(c, live_dns, PreflightError)\n    if c.net_action != "dns":\n        return c\n    conn = _live_connection(c.static_iface)\n    if not conn:\n        raise PreflightError(f"No active NetworkManager connection on {c.static_iface} to set DNS on")\n    return replace(c, net_connection=conn)\n\n\ndef check_pubkey(key_text: str) -> None:\n    """sshd accepts only ed25519 and password auth is off, so any other key type would lock the admin out."""\n    with tempfile.NamedTemporaryFile("w", delete=False) as f:\n        f.write(key_text)\n    try:\n        result = subprocess.run(["ssh-keygen", "-l", "-f", f.name], text=True, capture_output=True)\n    finally:\n        os.unlink(f.name)\n    info = result.stdout.strip()\n    if result.returncode != 0 or not info or any(not line.endswith("(ED25519)") for line in info.splitlines()):\n        raise PreflightError(f"Admin public key must be ssh-ed25519 only, got:\\n{info or result.stderr.strip()}")\n\n\ndef run(c: Config) -> Config:\n    """Return the config with network values resolved and the validated admin public key loaded."""\n    c = resolve_network(c)\n    key_text = load_pubkey(c.admin_pubkey_url, c.admin_pubkey_file, PreflightError)\n    check_pubkey(key_text)\n    return replace(c, admin_pubkey=key_text)\n')
    __stickytape_write_module('netcheck.py', b'"""Network settings shared by both distros: checks on STATIC_* values, and the decision of what to change.\n\nA value left unset keeps its live setting. Nothing is written unless STATIC_IP, STATIC_GATEWAY, STATIC_DNS or\nSTATIC_IFACE is set. STATIC_IP or STATIC_GATEWAY makes the address static (a DHCP address is frozen as it is);\nSTATIC_DNS alone changes only the DNS and leaves the address, DHCP or static, as it is.\n"""\n\nimport ipaddress\nimport json\nimport logging\nimport os\nimport re\nfrom dataclasses import replace\nfrom typing import Callable, TypeVar\n\nfrom base_actions import out, sh\n\nC = TypeVar("C")\n\nCIDR_RE = re.compile(r"^([0-9]{1,3}\\.){3}[0-9]{1,3}/[0-9]{1,2}$")\n\n\ndef check_static_network(static_ip: str, iface: str, gateway: str, error_cls: type = RuntimeError) -> None:\n    """The generated config describes a plain ethernet with an on-link gateway; refuse anything else up front."""\n    if any(os.path.exists(f"/sys/class/net/{iface}/{kind}") for kind in ("bridge", "bonding")):\n        raise error_cls(\n            f"{iface} is a bridge/bond, but the config written here describes a plain ethernet. "\n            f"Set STATIC_IFACE to the physical NIC, or manage {iface} yourself and leave STATIC_IP unset")\n    network = ipaddress.ip_interface(static_ip).network\n    if ipaddress.ip_address(gateway) not in network:\n        raise error_cls(\n            f"Gateway {gateway} is outside {network} (from STATIC_IP {static_ip}), "\n            f"fix STATIC_GATEWAY or the prefix length")\n\n\ndef is_cidr(value: str) -> bool:\n    """Shape and octet range: the regex alone accepts 192.168.1.300/24."""\n    if not CIDR_RE.match(value):\n        return False\n    try:\n        ipaddress.IPv4Interface(value)\n    except ValueError:\n        return False\n    return True\n\n\ndef check_ipv4(value: str, name: str, error_cls: type = RuntimeError) -> None:\n    try:\n        ipaddress.IPv4Address(value)\n    except ValueError:\n        raise error_cls(f"{name} must be an IPv4 address, got: {value}") from None\n\n\ndef default_route(*extra: str) -> dict:\n    routes = json.loads(sh("ip", "-j", "-4", "route", "show", "default", *extra).stdout or "[]")\n    return routes[0] if routes else {}\n\n\ndef live_ipv4(iface: str) -> dict:\n    """First IPv4 address on iface as iproute2 reports it (local, prefixlen, dynamic); {} if none."""\n    for entry in json.loads(out("ip", "-j", "-4", "addr", "show", "dev", iface) or "[]"):\n        for addr in entry.get("addr_info", []):\n            return addr\n    return {}\n\n\ndef resolve_network(c: C, live_dns: Callable[[str], list[str]], error_cls: type = RuntimeError) -> C:\n    """Decide the network change for config c. live_dns(iface) gives the DNS servers in use on iface."""\n    if not any((c.static_ip, c.static_gateway, c.static_dns, c.static_iface)):\n        return c\n    if c.static_ip and not is_cidr(c.static_ip):\n        raise error_cls(f"STATIC_IP must be IPv4 CIDR (e.g. 192.168.1.50/24), got: {c.static_ip}")\n    if c.static_gateway:\n        check_ipv4(c.static_gateway, "STATIC_GATEWAY", error_cls)\n    for server in c.static_dns.split():\n        check_ipv4(server, "STATIC_DNS", error_cls)\n    iface = c.static_iface or default_route().get("dev", "")\n    if not iface:\n        raise error_cls("Could not detect the default-route interface, set STATIC_IFACE")\n    if c.static_ip or c.static_gateway:\n        return _static_address(c, iface, live_dns, error_cls)\n    if c.static_dns:\n        return replace(c, static_iface=iface, net_action="dns", net_dhcp=bool(live_ipv4(iface).get("dynamic")))\n    logging.warning("STATIC_IFACE alone changes nothing; set STATIC_IP, STATIC_GATEWAY or STATIC_DNS as well")\n    return replace(c, static_iface=iface)\n\n\ndef _static_address(c: C, iface: str, live_dns: Callable[[str], list[str]], error_cls: type) -> C:\n    live = live_ipv4(iface)\n    if c.static_ip:\n        ip = c.static_ip\n    elif live:\n        ip = f"{live[\'local\']}/{live[\'prefixlen\']}"\n        if live.get("dynamic"):\n            logging.warning("STATIC_IP not set: the current DHCP address %s on %s becomes a static address", ip, iface)\n    else:\n        raise error_cls(f"{iface} has no IPv4 address to keep, set STATIC_IP")\n    gateway = c.static_gateway or default_route("dev", iface).get("gateway", "")\n    if not gateway:\n        raise error_cls(f"Could not detect the default gateway on {iface}, set STATIC_GATEWAY")\n    check_static_network(ip, iface, gateway, error_cls)\n    dns = c.static_dns or " ".join(live_dns(iface))\n    if not dns:\n        logging.warning("No DNS servers set or found on %s: the static config will have none", iface)\n    return replace(c, static_iface=iface, static_ip=ip, static_gateway=gateway, static_dns=dns, net_action="static")\n')
    __stickytape_write_module('pubkey.py', b'"""Load the admin public key: from a local file when given, otherwise downloaded from the configured URL."""\n\nimport http.client\nimport socket\nimport urllib.request\n\nCONNECT_TIMEOUT = 10  # seconds per address before the next one is tried\n\n\ndef _connect(host: str, port: int, timeout: float) -> socket.socket:\n    """Connect to host trying IPv4 addresses before IPv6, each with a short timeout.\n\n    Some networks publish AAAA records they cannot reach. urllib then waits the full timeout on each of those\n    addresses, one after another, before it reaches an address that works. IPv4 first avoids that stall.\n    """\n    infos = socket.getaddrinfo(host, port, type=socket.SOCK_STREAM)\n    infos.sort(key=lambda info: info[0] != socket.AF_INET)  # stable: IPv4 first, the resolver\'s order within each family\n    last_error: OSError = OSError(f"no address found for {host}")\n    for family, kind, proto, _, address in infos:\n        sock = socket.socket(family, kind, proto)\n        sock.settimeout(min(CONNECT_TIMEOUT, timeout))\n        try:\n            sock.connect(address)\n        except OSError as exc:\n            sock.close()\n            last_error = exc\n            continue\n        sock.settimeout(timeout)\n        return sock\n    raise last_error\n\n\nclass _IPv4FirstHTTPSConnection(http.client.HTTPSConnection):\n    def connect(self) -> None:\n        if self._tunnel_host:  # through a proxy: the proxy is the host to connect to, so keep urllib\'s own path\n            super().connect()\n            return\n        self.sock = self._context.wrap_socket(_connect(self.host, self.port, self.timeout), server_hostname=self.host)\n\n\nclass _IPv4FirstHTTPSHandler(urllib.request.HTTPSHandler):\n    def https_open(self, req):\n        return self.do_open(_IPv4FirstHTTPSConnection, req, context=self._context)\n\n\ndef _open(url: str, timeout: float):\n    return urllib.request.build_opener(_IPv4FirstHTTPSHandler).open(url, timeout=timeout)\n\n\ndef load_pubkey(url: str, local_file: str, error_cls: type = RuntimeError) -> str:\n    """A local file (ADMIN_PUBKEY_FILE) wins, so the run works offline; a failed download names that escape hatch."""\n    if local_file:\n        try:\n            with open(local_file, encoding="utf-8") as f:\n                return f.read()\n        except OSError as exc:\n            raise error_cls(f"Cannot read admin public key file {local_file}: {exc}") from exc\n    try:\n        with _open(url, timeout=30) as response:  # downloaded now, installed later\n            return response.read().decode("utf-8")\n    except (OSError, ValueError) as exc:  # URLError, timeouts and HTTPError are all OSError\n        raise error_cls(\n            f"Could not download the admin public key from {url}: {exc}\\n"\n            "Offline? Copy the key to this machine and re-run with ADMIN_PUBKEY_FILE=/path/to/key.pub "\n            "(after sudo, like the other overrides).") from exc\n')
    __stickytape_write_module('sections/prune.py', b'"""Remove every other regular login user. Runs last among the account steps.\n\nOnly regular accounts (UID_MIN..UID_MAX from login.defs) are candidates. Preview: the default check run lists who would be removed.\n"""\n\nimport logging\nimport re\nimport time\nfrom pathlib import Path\n\nfrom actions import Func, ok, sh\nfrom config import Config\n\nlog = logging.getLogger(__name__)\n\n\ndef _uid_range() -> tuple[int, int]:\n    values = {}\n    for line in Path("/etc/login.defs").read_text().splitlines():\n        parts = line.split()\n        if len(parts) >= 2 and parts[0] in ("UID_MIN", "UID_MAX"):\n            values[parts[0]] = int(parts[1])\n    return values.get("UID_MIN", 1000), values.get("UID_MAX", 60000)\n\n\ndef _accounts_ready(c: Config) -> bool:\n    """The admin and service accounts exist, the admin is in the admin group, and the admin key is installed."""\n    import grp\n    import pwd\n    try:\n        pwd.getpwnam(c.admin_user)\n        pwd.getpwnam(c.service_user)\n        if c.admin_user not in grp.getgrnam(c.admin_group).gr_mem:\n            return False\n    except KeyError:\n        return False\n    fields = c.admin_pubkey.split()\n    if len(fields) < 2:\n        return False\n    try:\n        return fields[1] in Path(c.admin_authorized_keys).read_text()\n    except OSError:\n        return False\n\n\ndef stale_users(c: Config) -> list[str]:\n    import pwd\n    low, high = _uid_range()\n    keep = {c.admin_user, c.service_user}\n    # The account that ran sudo goes too, but only once admin and service accounts are in place\n    if c.sudo_user and not _accounts_ready(c):\n        keep.add(c.sudo_user)\n    return [u.pw_name for u in pwd.getpwall() if low <= u.pw_uid <= high and u.pw_name not in keep]\n\n\ndef _remove(c: Config, user: str) -> None:\n    log.info("Removing user %s", user)\n    sh("usermod", "-L", "-s", "/sbin/nologin", user)\n    sh("pkill", "-KILL", "-u", user, check=False)\n    for _ in range(50):  # userdel refuses while processes remain: wait up to ~10s\n        if not ok("pgrep", "-u", user):\n            break\n        time.sleep(0.2)\n    # Drop sudoers grants that name this user (e.g. cloud-init\'s 90-cloud-init-users)\n    pattern = re.compile(rf"^{re.escape(user)}\\s", re.MULTILINE)\n    for f in Path(c.sudoers_dir).iterdir():\n        if f.is_file() and pattern.search(f.read_text(errors="replace")):\n            f.unlink()\n    if sh("userdel", "-r", user, check=False).returncode != 0:\n        log.warning("could not fully remove %s", user)\n\n\ndef _run(c: Config) -> None:\n    if c.sudo_user and not _accounts_ready(c):\n        log.warning("keeping %s (the account that ran sudo): admin and service accounts are not ready", c.sudo_user)\n    for user in stale_users(c):\n        _remove(c, user)\n\n\ndef actions(c: Config):\n    def pre() -> bool:\n        users = stale_users(c)\n        action.precheck_detail = f"would remove: {\', \'.join(users)}" if users else ""  # shown by the check run\n        return not users\n\n    action = Func(\n        name="remove other login users",\n        run=lambda: _run(c),\n        pre=pre,\n        post=lambda: not stale_users(c),\n    )\n    return [action]\n')
